mapper.select:
JOIN host_organizations o ON o.id=h.organization_id WHERE h.status='ENABLED' AND p.lifecycle_status='ACTIVE' AND o.operational_status='ENABLED' AND o.verification_status='VERIFIED'
AND (p.title ILIKE CONCAT('%',#{query},'%') OR p.address ILIKE CONCAT('%',#{query},'%'))
ORDER BY h.created_at DESC LIMIT #{limit} OFFSET #{offset}



    AND h.status=#{status}

