ORDER BY h.created_at DESC LIMIT #{limit} OFFSET #{offset}

mapper.insert:
WITH dates AS ( SELECT day::date AS day FROM generate_series(#{startDate}::date, #{endDate}::date, interval '1 day') day
WHERE EXTRACT(ISODOW FROM day)::int IN #{dayOfWeek}
) INSERT INTO rate_plan_daily_rates (rate_plan_id,rate_date,price,stop_sell,min_stay,max_stay, closed_to_arrival,closed_to_departure,min_advance_days,max_advance_days,data_version,updated_by,updated_at) SELECT #{ratePlanId},d.day, CASE WHEN CAST(#{clearFieldsJson} AS jsonb) ? 'PRICE' THEN NULL ELSE #{price} END, CASE WHEN CAST(#{clearFieldsJson} AS jsonb) ? 'STOP_SELL' THEN false ELSE COALESCE(#{stopSell},false) END, CASE WHEN CAST(#{clearFieldsJson} AS jsonb) ? 'MIN_STAY' THEN NULL ELSE #{minStay} END, CASE WHEN CAST(#{clearFieldsJson} AS jsonb) ? 'MAX_STAY' THEN NULL ELSE #{maxStay} END, CASE WHEN CAST(#{clearFieldsJson} AS jsonb) ? 'CLOSED_TO_ARRIVAL' THEN false ELSE COALESCE(#{closedToArrival},false) END, CASE WHEN CAST(#{clearFieldsJson} AS jsonb) ? 'CLOSED_TO_DEPARTURE' THEN false ELSE COALESCE(#{closedToDeparture},false) END, CASE WHEN CAST(#{clearFieldsJson} AS jsonb) ? 'MIN_ADVANCE_DAYS' THEN NULL ELSE #{minAdvanceDays} END, CASE WHEN CAST(#{clearFieldsJson} AS jsonb) ? 'MAX_ADVANCE_DAYS' THEN NULL ELSE #{maxAdvanceDays} END, 1,#{updatedBy},#{updatedAt} FROM dates d ON CONFLICT (rate_plan_id,rate_date) DO UPDATE SET price=CASE WHEN CAST(#{clearFieldsJson} AS jsonb) ? 'PRICE' THEN NULL ELSE COALESCE(#{price},rate_plan_daily_rates.price) END, stop_sell=CASE WHEN CAST(#{clearFieldsJson} AS jsonb) ? 'STOP_SELL' THEN false ELSE COALESCE(#{stopSell},rate_plan_daily_rates.stop_sell) END, min_stay=CASE WHEN CAST(#{clearFieldsJson} AS jsonb) ? 'MIN_STAY' THEN NULL ELSE COALESCE(#{minStay},rate_plan_daily_rates.min_stay) END, max_stay=CASE WHEN CAST(#{clearFieldsJson} AS jsonb) ? 'MAX_STAY' THEN NULL ELSE COALESCE(#{maxStay},rate_plan_daily_rates.max_stay) END, closed_to_arrival=CASE WHEN CAST(#{clearFieldsJson} AS jsonb) ? 'CLOSED_TO_ARRIVAL' THEN false ELSE COALESCE(#{closedToArrival},rate_plan_daily_rates.closed_to_arrival) END, closed_to_departure=CASE WHEN CAST(#{clearFieldsJson} AS jsonb) ? 'CLOSED_TO_DEPARTURE' THEN false ELSE COALESCE(#{closedToDeparture},rate_plan_daily_rates.closed_to_departure) END, min_advance_days=CASE WHEN CAST(#{clearFieldsJson} AS jsonb) ? 'MIN_ADVANCE_DAYS' THEN NULL ELSE COALESCE(#{minAdvanceDays},rate_plan_daily_rates.min_advance_days) END, max_advance_days=CASE WHEN CAST(#{clearFieldsJson} AS jsonb) ? 'MAX_ADVANCE_DAYS' THEN NULL ELSE COALESCE(#{maxAdvanceDays},rate_plan_daily_rates.max_advance_days) END, data_version=rate_plan_daily_rates.data_version+1,updated_by=#{updatedBy},updated_at=#{updatedAt} WHERE rate_plan_daily_rates.data_version=COALESCE((CAST(#{expectedVersionsJson} AS jsonb)->>rate_plan_daily_rates.rate_date::text)::bigint,-1)

mapper.select:
SELECT i.*, (total_units-reserved_units-sold_units-blocked_units) AS available_units
FROM room_inventory_daily i WHERE room_type_id=#{roomTypeId}
  AND inventory_date BETWEEN #{startDate} AND #{endDate} ORDER BY inventory_date

mapper.update:
UPDATE room_inventory_daily SET reserved_units=reserved_units+#{quantity},data_version=data_version+1,
  updated_by=#{updatedBy},updated_at=#{updatedAt}
WHERE room_type_id=#{roomTypeId} AND inventory_date >=#{checkIn} AND inventory_date <#{checkOut}
  AND stop_sell=false AND reserved_units+sold_units+blocked_units+#{quantity}<=total_units
  AND EXISTS (SELECT 1 FROM rate_plans rp WHERE rp.id=#{ratePlanId} AND rp.room_type_id=#{roomTypeId} AND rp.status='ENABLED')
  AND NOT EXISTS (SELECT 1 FROM rate_plan_daily_rates rd WHERE rd.rate_plan_id=#{ratePlanId} AND rd.rate_date=inventory_date AND rd.stop_sell=true)

UPDATE room_inventory_daily SET reserved_units=reserved_units-#{quantity},sold_units=sold_units+#{quantity},
  data_version=data_version+1,updated_by=#{updatedBy},updated_at=#{updatedAt}
WHERE room_type_id=#{roomTypeId} AND inventory_date >=#{checkIn} AND inventory_date <#{checkOut}
  AND reserved_units>=#{quantity}

UPDATE room_inventory_daily SET
  reserved_units=reserved_units-CASE WHEN #{fromReserved} THEN #{quantity} ELSE 0 END,
  sold_units=sold_units-CASE WHEN #{fromReserved} THEN 0 ELSE #{quantity} END,
  data_version=data_version+1,updated_by=#{updatedBy},updated_at=#{updatedAt}
WHERE room_type_id=#{roomTypeId} AND inventory_date >=#{checkIn} AND inventory_date <#{checkOut}
  AND ((#{fromReserved} AND reserved_units>=#{quantity}) OR (NOT #{fromReserved} AND sold_units>=#{quantity}))

